using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest;

/// <summary>
/// Exercises HttpPaymentGateway against a fake HTTP handler, proving both the outbound
/// request shape and the parsing of the provider's response are correct.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_as_json()
    {
        JsonElement? capturedBody = null;
        Uri? capturedUri = null;
        var handler = new FakeHttpMessageHandler(async request =>
        {
            capturedUri = request.RequestUri;
            capturedBody = JsonSerializer.Deserialize<JsonElement>(await request.Content!.ReadAsStringAsync());
            return JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""");
        });
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        await gateway.AuthorizeAsync("ORD-1", new Money(42.50m, "eur"), CancellationToken.None);

        Assert.Equal("/v1/authorizations", capturedUri!.AbsolutePath);
        Assert.Equal("ORD-1", capturedBody!.Value.GetProperty("reference").GetString());
        Assert.Equal(42.50m, capturedBody!.Value.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", capturedBody!.Value.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_approved()
    {
        var handler = new FakeHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""")));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_200_response_with_declined_status_is_read_back_as_declined()
    {
        var handler = new FakeHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"declined"}""")));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-2", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_is_treated_as_a_refused_authorization_not_an_error()
    {
        var handler = new FakeHttpMessageHandler(_ =>
            Task.FromResult(new HttpResponseMessage(HttpStatusCode.PaymentRequired)));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-3", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_status_or_body_from_the_provider_and_it_is_declined_or_it_throws()
    {
        var handler = new FakeHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, "{}")));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        var outcome = await gateway.AuthorizeAsync("ORD-4", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_server_error_from_the_provider_surfaces_as_an_exception()
    {
        var handler = new FakeHttpMessageHandler(_ =>
            Task.FromResult(new HttpResponseMessage(HttpStatusCode.InternalServerError)));
        var gateway = new HttpPaymentGateway(CreateClient(handler));

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-5", new Money(10m, "USD"), CancellationToken.None));
    }

    private static HttpClient CreateClient(HttpMessageHandler handler) =>
        new(handler) { BaseAddress = new Uri("https://provider.example/") };

    private static HttpResponseMessage JsonResponse(HttpStatusCode status, string json) =>
        new(status) { Content = JsonContent.Create(JsonDocument.Parse(json).RootElement) };

    private sealed class FakeHttpMessageHandler(Func<HttpRequestMessage, Task<HttpResponseMessage>> respond) : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
            => respond(request);
    }
}

